/* Small marked-compatible fallback for offline packaged chat. */
(function () {
  if (window.marked) return;
  function esc(s) {
    return String(s || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }
  function inline(s) {
    return esc(s)
      .replace(/`([^`]+)`/g, "<code>$1</code>")
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      .replace(/\*([^*]+)\*/g, "<em>$1</em>");
  }
  window.marked = {
    setOptions: function () {},
    parse: function (text) {
      var parts = String(text || "").split(/```/);
      var html = "";
      for (var i = 0; i < parts.length; i++) {
        if (i % 2 === 1) {
          var block = parts[i].replace(/^[a-zA-Z0-9_-]+\n/, "");
          html += "<pre><code>" + esc(block) + "</code></pre>";
        } else {
          html += parts[i]
            .split(/\n{2,}/)
            .filter(Boolean)
            .map(function (p) {
              return "<p>" + inline(p).replace(/\n/g, "<br>") + "</p>";
            })
            .join("");
        }
      }
      return html || "";
    },
  };
})();
